import {createWorkspace,workspacePages} from './workspace.js';
import {extend} from './governance.mjs';
import {VERSION,roles,allowed,stages,seed,log,evaluateMatch,createApplication,saveMatch,sendCommission,recordVote,finalize,transfer,issue,verify,csv} from './model.mjs';
const KEY='unigo-gazi-myys-v1', $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=seed(),storageIssue=false;try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.version===VERSION&&roles[x.role]&&['applications','credentials','audit','programs','notifications','transfers','appeals','enrollments','qualityTasks','finance'].every(k=>Array.isArray(x[k]))&&x.policy)state=x;}catch{storageIssue=true;}
let toastTimer,selectedApplication=state.applications[0]?.id,matchResult=null,query='',filter='all',lastFocus;
const paths={home:'M3 11 12 3l9 8v10h-6v-7H9v7H3Z',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',file:'M14 2H5v20h14V7Zm0 0v5h5M8 12h8M8 16h6',arrows:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',badge:'M12 3a6 6 0 1 0 0 12 6 6 0 0 0 0-12ZM8 14 6 22l6-3 6 3-2-8',network:'M3 3h6v6H3ZM15 15h6v6h-6ZM9 6h6a3 3 0 0 1 3 3v6M6 9v6a3 3 0 0 0 3 3h6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM17 4a4 4 0 0 1 0 7M20 21v-2a4 4 0 0 0-3-3.8',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3Zm9 2v16',layers:'m12 2 10 5-10 5L2 7Zm10 10-10 5L2 12m20 5-10 5L2 17',shield:'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Zm-4-10 3 3 5-6',chart:'M3 3v18h18M7 17v-5M12 17V7M17 17v-8',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',arrow:'M4 12h16m-6-6 6 6-6 6',plus:'M12 4v16M4 12h16',check:'m5 12 4 4L19 6',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',bell:'M18 8a6 6 0 0 0-12 0c0 6-2 6-2 9h16c0-3-2-3-2-9M10 21h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',wallet:'M20 7V4H5a3 3 0 0 0 0 6h16v11H5a3 3 0 0 1-3-3V7M16 14h5',leaf:'M20 3S4 2 4 13a7 7 0 0 0 7 7C22 20 20 3 20 3ZM3 22l13-13',message:'M3 3h18v14H8l-5 4Z',briefcase:'M8 7V3h8v4M3 7h18v14H3ZM3 12l9 3 9-3M12 12v5'};
const icon=(n)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const pages=[['overview','Genel bakış','grid','ÇALIŞMA ALANI'],['applications','Başvuru merkezi','file'],['catalog','Program kataloğu','book'],['matching','AKTS ve kredi eşleştirme','arrows','AKADEMİK YÖNETİŞİM'],['outcomes','Öğrenme çıktıları','layers'],['commission','Komisyon kararları','users'],['appeals','İtiraz ve revizyon','message'],['credentials','Rozet ve sertifikalar','badge','BELGELENDİRME VE ENTEGRASYON'],['wallet','Dijital yeterlilik cüzdanı','wallet'],['obs','OBS ve transkript','network'],['integrations','Entegrasyon merkezi','settings'],['pathways','Öğrenme yolları','layers','KALİTE VE OPERASYON'],['quality','Kalite ve etki analizi','chart'],['finance','Finans ve mutabakat','briefcase'],['notifications','Bildirimler ve görevler','bell'],['audit','Denetim izi','clock'],['settings','Kurumsal kurallar','shield']];
pages.splice(1,0,...workspacePages);
const title=()=>pages.find(p=>p[0]===route())?.[1]||'Genel bakış';
function route(){return location.hash.replace(/^#\/?/,'').split('/')[0]||'overview';}
function nav(id){query='';filter='all';location.hash='/'+id;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageIssue=true;toast('Tarayıcı kaydı kullanılamıyor. Bu oturumdaki değişiklikler yenilemede kaybolabilir.',true);}}
function toast(t,error=false){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').className='toast'+(error?' error-toast':'');$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function modal(t,body){lastFocus=document.activeElement;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(t)}</h2><button class="icon-btn" data-action="close" aria-label="Pencereyi kapat">✕</button></div><div class="dialog-body">${body}</div>`;$('#dialog').showModal();}
function close(){ $('#dialog').close();lastFocus?.focus();}
function heading(t,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">GAZİ ÜNİVERSİTESİ / MYYS</div><h1>${t}</h1><p>${desc}</p></div>${action}</div>`;}
const btn=(text,action,id='',style='')=>`<button class="btn ${style}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const link=(text,page,style='')=>`<a href="#/${page}" class="btn ${style}">${text}</a>`;
const tag=(t,type='neutral')=>`<span class="badge ${type}">${esc(t)}</span>`;
const status=a=>tag(stages[a.status]||a.status,({review:'warn',revision:'bad',commission:'info',approved:'good',rejected:'bad'})[a.status]);
const note=(action)=>allowed(state.role,action)?'':`<div class="permission-note">İşlem rolü: ${(permissionsText[action]||'Yetkili birim')}. Demo rolünü üst menüden değiştirebilirsiniz.</div>`;
const permissionsText={match:'Koordinatörlük, Komisyon veya Öğrenci İşleri',vote:'Komisyon üyesi',transfer:'Öğrenci İşleri',credential:'Öğrenci İşleri',review:'Koordinatörlük / GAZİSEM',policy:'Sistem yöneticisi',finance:'Mali İşler',quality:'Kalite Koordinatörlüğü',program:'Eğitici veya Koordinatörlük',appealReview:'Kalite Koordinatörlüğü'};
const visibleApplications=()=>state.role==='learner'?state.applications.filter(a=>a.owner==='DEMO-001'):state.applications;
const visibleCredentials=()=>state.role==='learner'?state.credentials.filter(c=>c.owner==='DEMO-001'):state.credentials;
function tableApplications(items,compact=false){return items.length?`<div class="table-wrap"><table><thead><tr><th>BAŞVURU / EĞİTİM</th>${compact?'':'<th>BAŞVURAN</th><th>İŞ YÜKÜ</th>'}<th>DURUM</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${esc(a.title)}</strong><small>${esc(a.id)} · ${esc(a.unit)}</small></td>${compact?'':`<td>${esc(a.learner)}</td><td>${a.hours} saat</td>`}<td>${status(a)}</td><td>${btn('İncele →','application',a.id,'link')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Bu görünümde başvuru bulunmuyor.</div>';}
function overview(){const apps=visibleApplications(),pending=apps.filter(a=>['review','commission','revision'].includes(a.status)),sum=apps.filter(a=>a.status==='approved').reduce((n,a)=>n+(a.decision?.ects||0),0);const modules=[['matching','arrows','blue','Akıllı AKTS ve kredi eşleştirme','Dış kazanımları iş yükü, öğrenme çıktısı ve kurumsal ölçütlerle karşılaştırın.','Eşleştirmeyi başlat'],['credentials','badge','teal','Dijital rozet ve sertifika','Belge sicili, doğrulama ve iptal durumunu tek merkezden yönetin.','Belgeyi doğrula'],['obs','network','purple','OBS ve transkript entegrasyonu','Onaylı kazanımları kontrollü aktarım kuyruğunda izleyin.','Aktarım merkezini aç'],['commission','users','gold','Komisyon karar otomasyonu','Gündem, raportör, gerekçeli oy ve karar arşivini birlikte takip edin.','Karar masasına git']];return heading('Öğrenmeyi görünür, kazanımı kalıcı kılın.','Gazi Üniversitesi mikro yeterlilik ekosistemine genel bakış.',btn(icon('plus')+' Yeni başvuru','new-application','','primary'))+`<section class="hero"><div class="hero-copy"><div class="hero-kicker">BİLGİDEN YETKİNLİĞE, YETKİNLİKTEN GELECEĞE</div><h2>Her öğrenme deneyimi,<br>izlenebilir bir kazanım.</h2><p>Öğrenme kanıtlarını akademik kararlara, doğrulanabilir belgelere ve kişisel gelişim yollarına bağlayan ortak çalışma alanı.</p><div class="button-row">${link('Programları keşfet '+icon('arrow'),'catalog')}${btn('İş akışını incele','tour')}</div></div><div class="hero-journey"><div class="journey-caption">BİR BAŞVURU. UÇTAN UCA İZLENEBİLİRLİK.</div><div class="flow">${[['file','Başvuru','Kanıt ve kazanım'],['arrows','Eşleştirme','AKTS önerisi'],['users','Komisyon','Akademik karar'],['badge','Dijital belge','Sicil ve doğrulama']].map(([i,t,s])=>`<div class="flow-node"><span>${icon(i)}</span><strong>${t}</strong><small>${s}</small></div>`).join('')}</div><div class="hero-foot">${icon('shield')} İnsan denetimi · Gerekçeli karar · Kurumsal hafıza</div></div></section><div class="stats">${[[apps.length,'Toplam başvuru','Örnek çalışma alanı','file'],[pending.length,'İnceleme bekleyen','Ön kontrol ve komisyon','clock'],[sum,'Onaylanan AKTS','Pilot karar toplamı','arrows'],[visibleCredentials().filter(c=>verify(state,c.code).valid).length,'Dijital yeterlilik','Örnek belge sicili','badge']].map(([n,t,d,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div class="stat-label">${t}</div><div class="stat-value">${n}</div><div class="stat-note">${d}</div></div>`).join('')}</div><div class="value-entry"><div><strong>Karar vericiler için yeni çalışma alanı</strong><p>Kurumsal değer, saha görüşmesi, kanıt inceleme ve canlı demo.</p></div>${link('Karar verici paneli →','executive','primary')}${link('3 dakikalık demo','demo')}</div><div class="section-heading"><h2>Yeterlilik yönetiminin dört temel modülü</h2><small>Birbirine bağlı iş akışları</small></div><div class="module-grid">${modules.map(([id,i,c,t,d,l])=>`<a class="module-card" href="#/${id}"><span class="module-icon ${c}">${icon(i)}</span><h3>${t}</h3><p>${d}</p><span class="module-bottom">${l}${icon('arrow')}</span></a>`).join('')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Son başvurular</h2><small>Akademik değerlendirme sürecinizin güncel görünümü</small></div>${link('Tümünü gör →','applications','link')}</div>${tableApplications(apps.slice(0,3),true)}<div class="panel-foot">Tüm kayıtlar sentetik örnektir; gösterge değerleri işlem yaptıkça güncellenir.</div></section><section class="panel"><div class="panel-head"><h2>Gündeminiz</h2>${icon('clock')}</div><div class="panel-body" style="padding-top:2px">${[['users','Komisyon değerlendirmesi',`${apps.filter(x=>x.status==='commission').length} dosya gerekçeli karar bekliyor.`,'commission','Gündemi aç'],['shield','Kalite ve iyileştirme',`${state.qualityTasks.filter(x=>x.status==='open').length} iyileştirme görevi açık.`,'quality','Görevleri incele'],['network','Kurumsal bağlantılar','OBS, EBYS ve SSO bağlantı hazırlığı.','integrations','Bağlantı durumları']].map(([i,t,d,p,l])=>`<div class="todo"><span class="todo-icon">${icon(i)}</span><div><strong>${t}</strong><p>${d}</p>${link(l+' →',p,'link')}</div></div>`).join('')}</div></section></div><div class="section-heading"><h2>Öğrenmenin bütün yaşam döngüsü</h2></div><div class="tag-row">${[['outcomes','Öğrenme çıktısı ve kanıt'],['wallet','Dijital cüzdan'],['pathways','Biriktirilebilir öğrenme yolları'],['appeals','İtiraz ve revizyon'],['quality','Kalite ve etki'],['audit','Denetim izi']].map(([p,t])=>link(t,p,'small')).join('')}</div>`;}
function applications(){const list=visibleApplications().filter(a=>(filter==='all'||a.status===filter)&&`${a.title} ${a.id} ${a.learner}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));return heading('Başvuru merkezi','Dış öğrenmeyi belgeleyin; başvuruları kanıt ve kazanımlarıyla takip edin.',btn(icon('plus')+' Yeni başvuru','new-application','','primary'))+`<div class="filters"><input id="search" aria-label="Başvurularda ara" placeholder="Başvuru, eğitim veya kişi ara…" value="${esc(query)}"><select id="filter" aria-label="Başvuru durumu"><option value="all">Tüm durumlar</option>${Object.entries(stages).map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select>${btn(icon('download')+' CSV indir','export-applications')}</div><div class="panel">${tableApplications(list)}</div>`;}
function catalog(){let items=state.programs.filter(p=>`${p.title} ${p.unit} ${p.category}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));return heading('Mikro yeterlilik kataloğu','Gazi birimleri için hazırlanmış örnek program önerileri.',btn(icon('plus')+' Program öner','new-program','','primary'))+`<div class="inline-info">Katalogdaki eğitimler tasarım örneğidir. Gerçek açılmış program, kayıt veya ücret ilanı değildir.</div><div class="filters"><input id="search" placeholder="Program, birim veya yetkinlik ara…" aria-label="Programlarda ara" value="${esc(query)}"></div><div class="three-grid">${items.map(p=>`<article class="panel program-card"><div class="program-art ${p.color||'blue'}">${icon(p.icon||'book')}<span>${esc(p.category)}</span></div><div class="panel-body"><h3>${esc(p.title)}</h3><p>${esc(p.unit)}</p><div class="meta-row"><span>${p.ects} AKTS önerisi</span><span>${p.hours} saat</span><span>${esc(p.mode)}</span></div>${btn('Programı incele '+icon('arrow'),'program',p.id,'small')}</div></article>`).join('')||'<div class="empty">Aramanızla eşleşen program yok.</div>'}</div>${note('program')}`;}
function matching(){const apps=visibleApplications().filter(a=>!['approved','rejected'].includes(a.status));const a=apps.find(x=>x.id===selectedApplication)||apps[0];if(a)selectedApplication=a.id;return heading('Akıllı AKTS ve kredi eşleştirme','İş yükünü hesaplayın, öğrenme çıktısı kapsamını inceleyin, öneriyi gerekçelendirin.')+`<div class="inline-info">Otomatik hesaplama karar desteğidir. AKTS ile yerel kredi farklı alanlardır; yerel kredi ve tanıma, yetkili akademik karar gerektirir. Kullanılan eşikler Gazi’nin teyit edilmiş kuralları değildir. <a href="#/evidence">Syllabus kanıt ifadelerini karşılaştır →</a></div>${a?`<div class="two-grid"><section class="panel"><div class="panel-head"><h2>Eşleştirme girdileri</h2>${tag('Açıklanabilir hesaplama','info')}</div><div class="panel-body"><form id="match-form"><label class="field">Başvuru seçin<select id="match-app" name="application">${apps.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${x.id} · ${esc(x.title)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Toplam öğrenen iş yükü (saat)<input name="hours" type="number" min="1" max="1800" step="0.5" value="${a.hours}" required><small>Ders, hazırlık, uygulama ve ölçme toplamı</small></label><label class="field">1 AKTS için saat<input name="per" type="number" value="${state.policy.hoursPerEcts}" readonly><small>Örnek politika · ${esc(state.policy.version)}</small></label></div><h3>Hedef öğrenme çıktılarını karşılayan kanıtlar</h3>${a.outcomes.map((o,i)=>`<label class="check"><input name="covered" value="${i}" type="checkbox" ${a.evidence?'checked':''}>${esc(o)}</label>`).join('')}<label class="check"><input name="evidence" type="checkbox" ${a.evidence?'checked':''}>Ölçme-değerlendirme kanıtı incelendi (örnek)</label><label class="check"><input name="issuer" type="checkbox" ${a.issuerChecked?'checked':''}>Belgeyi düzenleyen kurum teyit edildi (örnek)</label><button class="btn primary" type="submit">${icon('arrows')} Eşleştirmeyi hesapla</button></form>${note('match')}</div></section><section class="panel"><div class="panel-head"><h2>Öneri ve inceleme sonucu</h2></div><div class="panel-body" id="match-result">${matchResult?renderMatch(matchResult):a.match?renderMatch(a.match):`<div class="empty">${icon('arrows')}<p>Çıktı karşılıklarını ve kanıt kontrollerini seçip hesabı çalıştırın.</p></div>`}</div></section></div>`:'<div class="panel empty">Eşleştirme bekleyen başvuru bulunmuyor.</div>'}`;}
function renderMatch(m){return `<div class="metric-result"><div><strong>${m.ects}</strong><small>Önerilen AKTS</small></div><div><strong>%${m.coverage}</strong><small>Çıktı kapsamı</small></div></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,m.coverage))}%"></span></div><p class="body-copy">${esc(m.recommendation)}</p>${m.gaps?.length?`<ul class="list">${m.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul>`:''}<dl class="kv"><dt>Hesaplama</dt><dd>Toplam iş yükü ÷ örnek saat/AKTS parametresi</dd><dt>Kapsam</dt><dd>Karşılanan çıktı ÷ toplam çıktı</dd><dt>Yerel kredi</dt><dd>Otomatik dönüştürülmez; kurul değerlendirmesi gerekir.</dd><dt>Karar sahibi</dt><dd>Yetkili akademik komisyon</dd></dl><div class="button-row">${btn('Öneriyi dosyaya kaydet','save-match','','primary')}${link('Komisyon masası →','commission','small')}</div>`;}
function commission(){let apps=visibleApplications();return heading('Komisyon karar otomasyonu','Dosyadan gündeme, gerekçeli oydan karar arşivine tek akış.',btn('Karar arşivini indir','export-decisions'))+`<div class="stats">${[[apps.filter(a=>a.status==='commission').length,'Gündemdeki dosya'],[apps.filter(a=>a.status==='approved').length,'Pilot onay'],[apps.filter(a=>a.status==='revision').length,'Revizyon'],[apps.filter(a=>a.status==='rejected').length,'Uygun bulunmadı']].map(([n,t])=>`<div class="stat"><div class="stat-label">${t}</div><div class="stat-value">${n}</div></div>`).join('')}</div><div class="inline-info">Örnek toplantı yeter sayısı ${state.policy.quorum}, karar için en az ${state.policy.minVotes} oy ve katılanların çoğunluğu aranır. Çıkar çatışması olan üye oy kullanamaz. Bunlar kurumca teyit bekleyen pilot parametreleridir.</div><div class="panel"><div class="panel-head"><h2>Gündem ve karar arşivi</h2>${tag('Gerekçeli insan kararı','info')}</div>${tableApplications(apps.filter(a=>['commission','approved','rejected','revision'].includes(a.status)))}</div>${note('vote')}`;}
function credentials(){return heading('Dijital rozet ve sertifika doğrulama','Sicil kaydı, geçerlilik, iptal ve belge yaşam döngüsünü birlikte izleyin.')+`<div class="two-grid"><section class="panel"><div class="panel-head"><h2>Belge doğrula</h2>${icon('shield')}</div><div class="panel-body"><form id="verify-form"><label class="field">Belge doğrulama kodu<input name="code" required maxlength="80" value="GAZI-DEMO-2026-001" autocomplete="off"></label><button class="btn primary" type="submit">${icon('search')} Sicilde sorgula</button></form><div id="verify-result"></div><p class="body-copy">Bu pilot yalnız bu tarayıcıdaki örnek belge sicilini kontrol eder. Güvenli API, kurumsal elektronik mühür ve blokzincir bağlantısı henüz kurulmadı. <a href="#/evidence">Dosya inceleme ve imza deneyini aç →</a></p></div></section><section class="panel"><div class="panel-head"><h2>Güven ve taşınabilirlik</h2></div><div class="panel-body"><div class="status-list">${[['Kod ile sicil sorgusu','Pilot etkin','good'],['İptal / süre kontrolü','Pilot etkin','good'],['Güvenli doğrulama API’si','Kurum bağlantısı gerekli','warn'],['Elektronik mühür / imza','Sağlayıcı gerekli','warn'],['Blokzincir zaman damgası','İsteğe bağlı · Bağlı değil','neutral']].map(([a,b,c])=>`<div class="mini-stat"><span>${a}</span>${tag(b,c)}</div>`).join('')}</div></div></section></div><div class="panel"><div class="panel-head"><h2>Belge sicili</h2><small>Örnek belgeler</small></div><div class="table-wrap"><table><thead><tr><th>KAZANIM</th><th>AKTS</th><th>DURUM</th><th>İŞLEM</th></tr></thead><tbody>${visibleCredentials().map(c=>`<tr><td><strong>${esc(c.title)}</strong><small>${esc(c.code)}</small></td><td>${c.ects}</td><td>${tag(verify(state,c.code).label,verify(state,c.code).valid?'good':'bad')}</td><td><div class="button-row">${btn('Görüntüle','credential',c.code,'link')}${c.status==='valid'&&allowed(state.role,'revoke')?`<button class="btn link" data-g-action="expiry" data-id="${esc(c.code)}">Süre yönetimi</button>`:''}${c.status==='valid'&&allowed(state.role,'revoke')?btn('İptal et','revoke',c.code,'link'):''}</div></td></tr>`).join('')}</tbody></table></div></div>${note('credential')}`;}
function wallet(){return heading('Dijital yeterlilik cüzdanı','Kazanımlar, öğrenme çıktıları ve doğrulama bilgileri bir arada.')+`<div class="inline-info">Öğrenen rolünde yalnız Deniz Örnek’e ait pilot cüzdan gösterilir. İndirilen JSON, imzalı veya Open Badges sertifikalı bir belge değildir.</div><div class="three-grid">${visibleCredentials().map(c=>`<article class="credential"><img src="assets/gazi-logo.svg" alt="Gazi Üniversitesi logosu">${tag(verify(state,c.code).label,verify(state,c.code).valid?'good':'bad')}<h3>${esc(c.title)}</h3><small>${esc(c.holder)} · ${c.ects} AKTS</small><div class="sample-mark">ÖRNEK BELGE</div><div class="code">${esc(c.code)}</div><div class="button-row">${btn('Ayrıntı','credential',c.code,'small')}${btn(icon('download')+' JSON','export-credential',c.code,'small')}</div></article>`).join('')}</div>`;}
function obs(){const approved=visibleApplications().filter(a=>a.status==='approved');return heading('OBS ve transkript entegrasyonu','Onaylı kazanımların aktarım hazırlığını, alan eşlemelerini ve işlem tekrarlarını izleyin.')+`<div class="inline-info warn">Gazi OBS bağlantısı kurulmadı. <a href="#/delivery">Hata kuyruğu ve tekrar provası</a> · <a href="#/recognition">Tanıma sınırı kontrolü</a>. Buradaki işlemler sentetik verilerle aktarım provasıdır; gerçek transkripte yazma yapılmaz.</div><div class="two-grid"><section class="panel"><div class="panel-head"><h2>Aktarıma uygun kararlar</h2>${tag('Komisyon onayı gerekli','info')}</div><div class="panel-body">${approved.map(a=>`<div class="todo"><span class="todo-icon">${icon('file')}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.id)} · ${a.decision?.ects} AKTS · ${esc(a.learner)}</p><div class="button-row">${btn('Aktarım provası','transfer',a.id,'small')}${btn('Örnek belge oluştur','issue',a.id,'small')}</div></div></div>`).join('')||'<div class="empty">Önce komisyon onayını tamamlayın.</div>'}${note('transfer')}</div></section><section class="panel"><div class="panel-head"><h2>Veri eşleme sözlüğü</h2></div><div class="table-wrap"><table><thead><tr><th>MYYS ALANI</th><th>OBS HEDEFİ</th></tr></thead><tbody>${[['Öğrenen kimliği','Öğrenci numarası'],['Karar referansı','Kurul karar numarası'],['Onaylanan AKTS','Kazanılmış AKTS'],['Kazanım / program kodu','Transkript açıklaması'],['Belge doğrulama kodu','Belge referansı']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div><div class="panel-foot">Hedef alan adları Gazi OBS veri sözleşmesiyle teyit edilecek.</div></section></div><div class="panel"><div class="panel-head"><h2>Aktarım kuyruğu ve prova günlüğü</h2>${btn('CSV indir','export-transfers','','small')}</div>${state.transfers.length?`<div class="table-wrap"><table><thead><tr><th>BAŞVURU</th><th>AKTS</th><th>DURUM</th><th>KONTROL</th></tr></thead><tbody>${state.transfers.filter(t=>state.role!=='learner'||t.student==='DEMO-001').map(t=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(t.applicationId)}</small></td><td>${t.ects}</td><td>${tag(t.state,'good')}</td><td>Mükerrerlik koruması · Canlı gönderim yok</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aktarım provası henüz çalıştırılmadı.</div>'}</div>`;}
function outcomes(){return heading('Öğrenme çıktısı ve kanıt matrisi','Program tasarımını ölçme yöntemi, kanıt ve yeterlilik çerçevesiyle ilişkilendirin.')+`<div class="two-grid"><section class="panel"><div class="panel-head"><h2>Ölçülebilir çıktı kontrolü</h2></div><div class="panel-body"><form id="outcome-form"><label class="field">Öğrenme çıktıları (her satır bir çıktı)<textarea name="outcomes" rows="6" required>Veri kümesini temizler.\nVerileri görselleştirir.\nBulguları yorumlar.</textarea></label><label class="field">Ölçme / kanıt yöntemi<select name="method"><option>Uygulamalı proje ve rubrik</option><option>Performans görevi ve gözlem</option><option>Yazılı sınav ve cevap anahtarı</option><option>Portfolyo ve sözlü savunma</option></select></label><button class="btn primary">Çıktı matrisini oluştur</button></form><div id="outcome-result"></div></div></section><section class="panel"><div class="panel-head"><h2>Çerçeve ve program ilişkisi</h2></div><div class="panel-body"><div class="status-list">${[['TYÇ','Bilgi, beceri ve yetkinlik'],['AYÇ / EQF','Seviye ve sorumluluk / özerklik'],['TYYÇ','Yükseköğretim yeterlilikleri'],['Program çıktıları','Ders ve program hedefleri'],['Ölçme kanıtı','Rubrik, performans ve ürün']].map(([a,b])=>`<div class="mini-stat"><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><p class="body-copy">Çerçeve seviyesi yalnız fiil eşlemesiyle belirlenmez. Karmaşıklık, özerklik ve kanıt düzeyi akademik değerlendirmeyle teyit edilir. Bu ekran deterministik bir yazım kontrolüdür; yapay zekâ servisi kullanmaz.</p></div></section></div>`;}
const systems=[['OBS','Öğrenci İşleri','Kazanılmış kredi ve transkript','Öğrenci kimliği, karar ve AKTS'],['EBYS / e-imza','Yetkili kurul ve evrak birimi','Karar ve belge arşivi','Karar numarası, imza ve sürüm'],['SSO / kurumsal kimlik','Bilgi İşlem','Güvenli kimlik ve rol yönetimi','Kurumsal kullanıcı ve birim'],['ÖYS / LMS','Eğitici ve öğrenme birimi','Öğrenme ve değerlendirme kanıtı','Tamamlama, ölçme ve kanıt'],['GAZİSEM','Sürekli Eğitim Merkezi','Program ve dönem yönetimi','Katalog, kontenjan ve başvuru'],['Mali sistemler','Mali İşler / Döner Sermaye','Tahsilat ve mutabakat','Onaylı ücret ve işlem referansı'],['Doğrulama API’si','Belgelendirme / Bilgi İşlem','Belge sicili ve iptal','Asgari belge üst verisi'],['E-posta / SMS','İletişim ve Bilgi İşlem','Durum ve görev bildirimleri','Tercih, alıcı ve şablon']];
function integrations(){return heading('Entegrasyon merkezi','Kurum sistemleri için veri sahibi, aktarım amacı ve bağlantı hazırlığı.')+`<div class="inline-info">Bağlantılar tasarım düzeyindedir. API adresi, yetkilendirme, veri sözleşmesi ve kurum test ortamı sağlanmadan canlı bağlantı açılmaz. Sistem varlığı, erişim yetkisi anlamına gelmez.</div><div class="three-grid">${systems.map(([id,owner,goal,fields])=>`<section class="panel"><div class="panel-body"><span class="module-icon blue">${icon('network')}</span><h3 class="spaced">${id}</h3><p class="body-copy">${goal}</p>${tag('Bağlı değil','warn')}<dl class="kv"><dt>Veri sahibi</dt><dd>${owner}</dd><dt>Asgari kapsam</dt><dd>${fields}</dd><dt>Son kontrol</dt><dd>${state.integrationChecks[id]?'Yerel hazırlık kontrolü yapıldı':'Henüz kontrol edilmedi'}</dd></dl>${btn('Hazırlığı incele','integration',id,'small')}</div></section>`).join('')}</div>`;}
function pathways(){return heading('Biriktirilebilir öğrenme yolları','Mikro kazanımları bir gelişim yolunda toplayın, eksik halkaları görünür kılın.')+`<div class="panel"><div class="panel-head"><div><h2>Dijital yetkinlik gelişim yolu</h2><small>Örnek yol · Toplam 6 AKTS önerisi</small></div>${tag('Otomatik diploma / muafiyet vermez','info')}</div><div class="panel-body"><div class="pathway">${['P06','P01','P02'].map((id,i)=>{const p=state.programs.find(x=>x.id===id),joined=state.enrollments.includes(id);return `<div class="path-step"><span class="module-icon ${p.color}">${icon(p.icon)}</span><strong>${i+1}. ${esc(p.title)}</strong><span>${p.ects} AKTS · ${p.hours} saat</span><div class="tag-row">${tag(joined?'Planınızda':'Planınıza eklenebilir',joined?'info':'neutral')}</div>${btn(joined?'Programı incele':'Planıma ekle',joined?'program':'enroll',id,'small')}</div>`;}).join('')}</div><p class="body-copy">Biriktirme ve başka bir yeterliliğe tanıma, hedef programın kabul koşullarına ve yetkili akademik karara bağlıdır. Aynı öğrenme kanıtının iki kez kredilendirilmesi ayrıca kontrol edilir.</p></div></div><div class="panel"><div class="panel-head"><h2>Öğrenme planım</h2></div><div class="panel-body">${state.enrollments.map(id=>{const p=state.programs.find(x=>x.id===id);return p?`<div class="mini-stat"><span>${esc(p.title)}</span>${btn('Plandan çıkar','unenroll',id,'link')}</div>`:'';}).join('')||'<p class="body-copy">Henüz bir program eklenmedi.</p>'}</div></div>`;}
function quality(){const apps=visibleApplications(),total=apps.length,withEvidence=apps.filter(a=>a.evidence).length,decided=apps.filter(a=>['approved','rejected'].includes(a.status)).length;return heading('Kalite güvencesi ve etki analizi','Kanıt kapsamını, karar süreçlerini ve iyileştirme görevlerini takip edin.',btn(icon('download')+' Rapor indir','export-quality'))+`<div class="two-grid"><section class="panel"><div class="panel-head"><h2>Çalışma alanı göstergeleri</h2>${tag('Pilot veriden hesaplanır','info')}</div><div class="panel-body">${[['Ölçme kanıtı bulunan dosyalar',withEvidence,total],['Karara bağlanan dosyalar',decided,total],['Tamamlanan iyileştirmeler',state.qualityTasks.filter(q=>q.status==='done').length,state.qualityTasks.length]].map(([t,n,d])=>`<div class="score-row"><span>${t}</span><strong>${n}/${d}</strong></div><div class="progress"><span style="width:${d?100*n/d:0}%"></span></div>`).join('')}<p class="body-copy">Memnuniyet, istihdam etkisi ve gerçek tamamlama oranı için doğrulanmış veri bulunmuyor; bu alanlarda performans iddiası üretilmez.</p></div></section><section class="panel"><div class="panel-head"><h2>PUKÖ ve iyileştirme görevleri</h2>${btn('+ Görev','new-task','','small')}</div><div class="panel-body">${state.qualityTasks.map(q=>`<div class="todo"><span class="todo-icon">${icon(q.status==='done'?'check':'clock')}</span><div><strong>${esc(q.title)}</strong><p>${esc(q.owner)} · Hedef: ${esc(q.due)}</p>${btn(q.status==='done'?'Yeniden aç':'Tamamlandı işaretle','toggle-task',q.id,'link')}</div></div>`).join('')}${note('quality')}</div></section></div>`;}
function appeals(){return heading('İtiraz ve revizyon takibi','Gerekçeyi, dosya sürümünü ve bağımsız inceleme sonucunu kayıt altına alın.',btn('+ İtiraz kaydı','new-appeal','','primary'))+`<div class="inline-info">İtiraz, ilk kararı değiştirmez; ayrı bir inceleme kaydı açar. Pilot bağımsız inceleme rolü Kalite Koordinatörlüğüdür; kurumun gerçek merci ve süreleri teyit edilmelidir.</div><div class="panel"><div class="panel-head"><h2>İtiraz dosyaları</h2></div>${state.appeals.length?`<div class="table-wrap"><table><thead><tr><th>DOSYA</th><th>GEREKÇE</th><th>DURUM</th><th></th></tr></thead><tbody>${state.appeals.filter(a=>state.role!=='learner'||a.owner==='DEMO-001').map(a=>`<tr><td><strong>${esc(a.applicationId)}</strong><small>${esc(a.id)}</small></td><td>${esc(a.reason.slice(0,70))}</td><td>${tag(a.status==='open'?'Bağımsız inceleme':'İncelendi',a.status==='open'?'warn':'good')}</td><td>${btn('İncele','appeal',a.id,'link')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Henüz itiraz kaydı yok. Karara bağlanmış bir örnek dosya üzerinden başlatabilirsiniz.</div>'}</div>`;}
function finance(){return heading('Finans ve mutabakat','Örnek ücret ve tahsilat durumlarının görev ayrılığıyla takibi.')+`<div class="inline-info">Bu bölüm ödeme almaz, fatura üretmez ve muhasebe sistemine veri göndermez. Tutarlar yalnız örnek senaryodur.</div><div class="panel"><div class="panel-head"><h2>Örnek mutabakat kuyruğu</h2>${tag('Mali İşler rolü','info')}</div><div class="table-wrap"><table><thead><tr><th>PROGRAM</th><th>ÖRNEK TUTAR</th><th>DURUM</th><th></th></tr></thead><tbody>${state.finance.map(f=>`<tr><td>${esc(f.program)}</td><td>${f.amount.toLocaleString('tr-TR')} TL</td><td>${tag(f.state,f.state==='Mutabık'?'good':'warn')}</td><td>${f.state==='Bekliyor'?btn('Mutabakat provası','reconcile',f.id,'small'):'Kayıt tamamlandı'}</td></tr>`).join('')}</tbody></table></div></div>${note('finance')}`;}
function notifications(){return heading('Bildirimler ve görevler','Başvuru, komisyon ve kalite gündemini tek yerden izleyin.',btn('Tümünü okundu işaretle','read-all'))+state.notifications.map(n=>`<section class="panel notification-card ${n.read?'':'unread'}"><div class="panel-body"><div class="section-heading"><h3>${esc(n.title)}</h3>${tag(n.read?'Okundu':'Yeni',n.read?'neutral':'info')}</div><p class="body-copy">${esc(n.body)}</p>${n.read?'':btn('Okundu işaretle','read',n.id,'link')}</div></section>`).join('')+`<p class="body-copy">Bildirimler uygulama içidir. E-posta ve SMS gönderimi bağlı değildir.</p>`;}
function audit(){return heading('Denetim izi ve işlem arşivi','Kim, hangi rolde, hangi dosyada, hangi işlemi yaptı?',btn(icon('download')+' Denetim kaydı indir','export-audit'))+`<div class="inline-info">Pilot günlük bu tarayıcıda tutulur ve değiştirilemez bir sunucu günlüğü değildir. Üretim kullanımında sunucu kaydı, erişim denetimi ve saklama politikası gerekir.</div><section class="panel"><div class="panel-body"><div class="timeline">${state.audit.slice(0,100).map(a=>`<div class="timeline-item"><strong>${esc(a.action)}</strong><small>${new Date(a.at).toLocaleString('tr-TR')} · ${esc(roles[a.role]||'Sistem')} · ${esc(a.entity)}</small><span class="muted">${esc(a.detail)}</span></div>`).join('')}</div></div></section>`;}
function settings(){return heading('Kurumsal kurallar ve kaynaklar','Kurum politikalarını sürümleyin; varsayımı resmî karardan ayırın.')+`<div class="inline-info warn">Gazi Üniversitesi’nin mikro yeterlilik yönergesi ve bu pilotun kurumsal onayı doğrulanmadı. Aşağıdaki parametreler örnektir; resmî kuralların yerine geçmez.</div><div class="two-grid"><section class="panel"><div class="panel-head"><h2>Pilot kural profili</h2>${tag(state.policy.version,'info')}</div><div class="panel-body"><form id="policy-form"><label class="field">1 AKTS için iş yükü (saat)<input name="hours" type="number" min="25" max="30" value="${state.policy.hoursPerEcts}" required></label><label class="field">Öğrenme çıktısı kapsam eşiği (%)<input name="coverage" type="number" min="1" max="100" value="${state.policy.minCoverage}" required></label><div class="form-grid"><label class="field">Toplantı yeter sayısı<input name="quorum" type="number" min="3" max="5" value="${state.policy.quorum}" required></label><label class="field">Asgari aynı yönde oy<input name="votes" type="number" min="2" max="5" value="${state.policy.minVotes}" required></label></div><button class="btn primary">Yeni pilot sürümü kaydet</button></form>${note('policy')}</div></section><section class="panel"><div class="panel-head"><h2>Kaynak ve teyit merkezi</h2></div><div class="panel-body"><div class="status-list">${[['Gazi kurumsal kimlik kılavuzu','https://gazi.edu.tr/view/page/237161/kurumsal-kimlik-kilavuzu'],['Gazi eğitim planlama birimi','https://akts-egitimplanlama.gazi.edu.tr/view/page/241480'],['Avrupa mikro yeterlilik yaklaşımı','https://education.ec.europa.eu/education-levels/higher-education/micro-credentials'],['AYÇ seviye tanımları','https://europass.europa.eu/en/description-eight-eqf-levels']].map(([t,u])=>`<a class="source-link body-copy" href="${u}" target="_blank" rel="noopener">${t} ↗</a>`).join('')}</div><h3 class="spaced">Kurumca tamamlanacak alanlar</h3><ul class="list"><li>Senato / yetkili kurul kararı ve yürürlük tarihi</li><li>Tanıma, yerel kredi ve azami AKTS koşulları</li><li>Komisyon üye atamaları ve itiraz mercii</li><li>OBS veri sözleşmesi ve test erişimi</li><li>Belge mühür / imza ve doğrulama yetkisi</li><li>KVKK, saklama süresi ve rol yetkileri</li></ul></div></section></div><section class="panel"><div class="panel-body"><h2>Pilot verisi</h2><p class="body-copy">Çalışmalar bu tarayıcıya özeldir. Gerçek kişisel veri girmeyin. Yedek dosyasını JSON olarak indirebilir veya yalnız bu Gazi pilotunu başlangıç örneklerine döndürebilirsiniz.</p><div class="button-row">${btn('Pilot yedeğini indir','backup')}${btn('Örnek veriyi sıfırla','reset-confirm','','danger')}</div></div></section>`;}
const workspace=createWorkspace({getState:()=>state,save,render,heading,esc,tag,link,modal,close,toast,download});
const renderers={...workspace,overview,applications,catalog,matching,commission,credentials,wallet,obs,outcomes,integrations,pathways,quality,appeals,finance,notifications,audit,settings};
function render(){extend(state);const p=route();$('#nav').innerHTML=pages.map(([id,t,i,g])=>(g?`<div class="nav-group">${g}</div>`:'')+`<a class="nav-link ${p===id?'active':''}" href="#/${id}" ${p===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='applications'?`<span class="nav-count">${visibleApplications().length}</span>`:''}</a>`).join('');$('#role').innerHTML=Object.entries(roles).map(([v,t])=>`<option value="${v}" ${v===state.role?'selected':''}>${t}</option>`).join('');$('#avatar').textContent=state.role==='learner'?'DÖ':'GK';$('#breadcrumb').textContent=title();$('#main').innerHTML=(storageIssue?'<div class="inline-info warn">Tarayıcı depolamasına erişilemedi. Bu oturumdaki işlemler kalıcı olmayabilir.</div>':'')+(renderers[p]||overview)();$('#notification-count').textContent=state.notifications.filter(n=>!n.read).length;document.title=`${title()} · Gazi Üniversitesi MYYS`;$('#sidebar').classList.remove('open');$('#veil').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function newApplication(){if(!allowed(state.role,'create'))throw Error('Yeni başvuru için Öğrenen veya Koordinatörlük rolünü seçin.');modal('Dış kazanım başvurusu',`<p>Deniz Örnek adına sentetik başvuru oluşturun. Gerçek kişi bilgisi veya belge yüklemeyin.</p><form id="application-form"><div class="form-grid"><label class="field full">Eğitimin adı<input name="title" maxlength="120" required></label><label class="field">Düzenleyen kurum (örnek)<input name="provider" maxlength="100" required></label><label class="field">İş yükü (saat)<input type="number" name="hours" min="1" max="1800" value="75" required></label><label class="field">Hedef birim<select name="unit">${['Mühendislik Fakültesi','Gazi Eğitim Fakültesi','Teknoloji Fakültesi','Sağlık Bilimleri Fakültesi','GAZİSEM'].map(u=>`<option>${u}</option>`).join('')}</select></label><label class="field">Hedef kazanım<input name="target" maxlength="120" required></label><label class="field full">Öğrenme çıktıları<textarea name="outcomes" required maxlength="2400" placeholder="Her satıra bir ölçülebilir öğrenme çıktısı yazın."></textarea></label></div><label class="check"><input name="evidence" type="checkbox">Ölçme kanıtı örneği mevcut</label><button type="submit" class="btn primary">Başvuruyu oluştur</button></form>`);}
function application(id){const a=visibleApplications().find(x=>x.id===id);if(!a)throw Error('Bu rolde başvuru bulunamadı.');modal(a.id+' · Başvuru dosyası',`${status(a)}<h2 class="spaced">${esc(a.title)}</h2><dl class="kv"><dt>Başvuran</dt><dd>${esc(a.learner)}</dd><dt>Kurum</dt><dd>${esc(a.provider)}</dd><dt>Hedef birim</dt><dd>${esc(a.unit)}</dd><dt>İş yükü</dt><dd>${a.hours} saat</dd><dt>Eşleme</dt><dd>${a.match?`${a.match.ects} AKTS · %${a.match.coverage} çıktı kapsamı`:'Henüz hesaplanmadı'}</dd><dt>Ölçme kanıtı</dt><dd>${a.evidence?'Örnek kanıt mevcut':'Eksik'}</dd><dt>Kurum teyidi</dt><dd>${a.issuerChecked?'Örnek teyit tamam':'Bekliyor'}</dd></dl><h3>Öğrenme çıktıları</h3><ul class="list">${a.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><div class="button-row">${!['approved','rejected'].includes(a.status)?btn('AKTS eşleştirmesine git','go-match',a.id):''}${['review','revision'].includes(a.status)?btn('Komisyona sevk et','send-commission',a.id,'primary'):''}${a.status==='commission'?btn('Gerekçeli oy kullan','vote',a.id,'primary'):''}${a.status==='approved'?btn('OBS aktarım merkezine git','go-obs')+btn('Örnek belge oluştur','issue',a.id):''}${['approved','rejected'].includes(a.status)?btn('Karar kaydını indir','decision',a.id):''}</div>${a.votes.length?`<h3 class="spaced">Komisyon oyları</h3>${a.votes.map(v=>`<div class="mini-stat"><span>${esc(v.member)}</span><strong>${({approve:'Uygun',revision:'Revizyon',reject:'Uygun değil'})[v.vote]}</strong></div>`).join('')}${a.status==='commission'?`<div class="spaced">${btn('Pilot kararı oluştur','finalize',a.id,'primary')}</div>`:''}`:''}${a.decision?`<div class="result-box"><strong>Karar gerekçesi</strong><p>${esc(a.decision.reason)}</p><small>Politika: ${esc(a.decision.policyVersion)}</small></div>`:''}`);}
function program(id){const p=state.programs.find(x=>x.id===id);modal(p.title,`${tag('Örnek program önerisi','info')}<dl class="kv"><dt>Birim</dt><dd>${esc(p.unit)}</dd><dt>İş yükü</dt><dd>${p.hours} saat / ${p.ects} AKTS önerisi</dd><dt>Yöntem</dt><dd>${esc(p.mode)}</dd></dl><h3>Öğrenme çıktıları</h3><ul class="list">${p.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><h3>Ölçme ve kanıt</h3><p>Uygulamalı görev, ürün portfolyosu ve rubrik temelli değerlendirme tasarımı.</p><div class="button-row">${btn(state.enrollments.includes(id)?'Plandan çıkar':'Öğrenme planıma ekle',state.enrollments.includes(id)?'unenroll':'enroll',id,'primary')}${link('Öğrenme yollarına git','pathways','small')}</div>`);}
function credential(code){const r=verify(state,code),c=r.credential;if(!c)throw Error(r.label);modal('Dijital yeterlilik · Örnek belge',`<div class="credential"><img src="assets/gazi-logo.svg" alt="Gazi Üniversitesi logosu">${tag(r.label,r.valid?'good':'bad')}<h3>${esc(c.title)}</h3><small>${esc(c.holder)} · ${c.ects} AKTS</small><div class="code">${esc(c.code)}</div><div class="sample-mark">ÖRNEK</div><ul class="list">${c.outcomes.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><dl class="kv"><dt>Düzenleme</dt><dd>${esc(c.issued)}</dd><dt>Süre</dt><dd>${c.expires||'Örnek belgede süre belirtilmedi'}</dd></dl></div><p>ÜniGO tanıtım ortamında üretilmiştir. Gazi Üniversitesi tarafından düzenlenmiş resmî belge değildir. Kriptografik imza veya blokzincir doğrulaması içermez.</p>${btn('Örnek kaydı JSON indir','export-credential',c.code,'primary')}`);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;try{switch(action){
 case 'close':close();return;
 case 'scope':modal('Gazi MYYS pilot kapsamı','<p>Gazi Üniversitesi için özelleştirilmiş etkileşimli ÜniGO tanıtım ortamıdır. Üniversitenin resmî başvuru sistemi değildir.</p><ul class="list"><li>Başvuru, eşleme, komisyon oylaması, örnek belge ve aktarım provası çalışır.</li><li>İşlemler bu tarayıcıda saklanır; cihazlar ve kullanıcılar arasında paylaşılmaz.</li><li>Demo rol seçimi gerçek kimlik doğrulama değildir.</li><li>OBS, EBYS, SSO, e-imza, doğrulama API’si ve blokzincir bağlı değildir.</li><li>Kurum yönergesi ve gerçek bağlantılar sağlanmadan resmî işlem yapılmaz.</li></ul>');return;
 case 'tour':modal('Bir kazanımın yolculuğu','<ol class="list"><li><strong>Öğrenen:</strong> Dış eğitimin iş yükü ve öğrenme çıktılarını girer.</li><li><strong>Koordinatörlük:</strong> Ölçme kanıtlarını kontrol eder, AKTS önerisini hesaplar ve dosyayı komisyona sevk eder.</li><li><strong>Komisyon:</strong> Üyeler ayrı gerekçeli oy kullanır; yeter sayı ve çoğunluk sağlanınca karar oluşturulur.</li><li><strong>Öğrenci İşleri:</strong> Onaylı kazanım için örnek belge ve OBS aktarım provası üretir.</li><li><strong>Öğrenen ve kalite:</strong> Cüzdan, itiraz ve denetim kayıtlarından sonucu izler.</li></ol><p>Her aşama için sağ üstteki demo rolünü değiştirin.</p>');return;
 case 'new-application':newApplication();return;
 case 'application':application(id);return;
 case 'program':program(id);return;
 case 'credential':credential(id);return;
 case 'go-match':selectedApplication=id;matchResult=null;close();nav('matching');return;
 case 'go-obs':close();nav('obs');return;
 case 'save-match':{if(!matchResult)throw Error('Kaydetmeden önce eşleştirmeyi yeniden hesaplayın.');saveMatch(state,selectedApplication,matchResult);const a=state.applications.find(a=>a.id===selectedApplication);a.hours=matchResult.hours;a.evidence=matchResult.evidence;a.issuerChecked=matchResult.issuerChecked;toast('AKTS önerisi dosyaya kaydedildi.');break;}
 case 'send-commission':sendCommission(state,id);close();toast('Dosya komisyon gündemine eklendi.');break;
 case 'vote':{if(!allowed(state.role,'vote'))throw Error('Komisyon üyesi rolünü seçin.');modal('Gerekçeli komisyon oyu',`<form id="vote-form" data-id="${esc(id)}"><label class="field">Demo üyesi<select name="member">${[1,2,3,4,5].map(n=>`<option>Üye ${n}</option>`).join('')}</select></label><label class="field">Görüş<select name="vote"><option value="approve">Uygun</option><option value="revision">Revizyon gerekli</option><option value="reject">Uygun değil</option></select></label><label class="field">Akademik gerekçe<textarea name="reason" minlength="12" maxlength="1600" required></textarea></label><label class="check"><input name="conflict" type="checkbox">Bu dosyada çıkar çatışmam var</label><button class="btn primary">Oyu kaydet</button><p>Bu, çok üyeli sürecin tek tarayıcıdaki simülasyonudur. Gerçek kimlik veya e-imza kullanılmaz.</p></form>`);return;}
 case 'finalize':finalize(state,id);close();toast('Pilot karar ve gerekçeler arşive alındı.');break;
 case 'transfer':transfer(state,id);toast('OBS provası tamamlandı. Gerçek veri gönderilmedi.');break;
 case 'issue':{const c=issue(state,id);toast('Örnek belge oluşturuldu: '+c.code);if($('#dialog').open)close();break;}
 case 'revoke':modal('Örnek belgeyi iptal et',`<form id="revoke-form" data-id="${esc(id)}"><label class="field">İptal gerekçesi<textarea name="reason" minlength="12" maxlength="800" required></textarea></label><button class="btn danger">Pilot kaydını iptal et</button></form>`);return;
 case 'export-credential':{const c=visibleCredentials().find(c=>c.code===id);if(!c)throw Error('Belge bu rolde görüntülenemiyor.');download(id+'.json',JSON.stringify({type:'UnsignedPilotCredential',official:false,issuer:'ÜniGO Gazi tanıtım ortamı',...c},null,2));return;}
 case 'export-applications':download('Gazi_MYYS_Basvurular.csv',csv([['Başvuru','Eğitim','Birim','Öğrenen','İş yükü','Durum'],...visibleApplications().map(a=>[a.id,a.title,a.unit,a.learner,a.hours,stages[a.status]])]),'text/csv;charset=utf-8');return;
 case 'export-transfers':download('Gazi_OBS_Aktarim_Provasi.csv',csv([['Başvuru','Kazanım','AKTS','Durum','Gerçek gönderim'],...state.transfers.filter(t=>state.role!=='learner'||t.student==='DEMO-001').map(t=>[t.applicationId,t.title,t.ects,t.state,'Hayır'])]),'text/csv;charset=utf-8');return;
 case 'export-audit':download('Gazi_Pilot_Denetim_Izi.json',JSON.stringify({official:false,audit:state.audit},null,2));return;
 case 'export-quality':download('Gazi_Pilot_Kalite_Raporu.json',JSON.stringify({official:false,generatedAt:new Date().toISOString(),applications:visibleApplications().length,evidence:visibleApplications().filter(a=>a.evidence).length,decisions:visibleApplications().filter(a=>a.decision).length,improvements:state.qualityTasks},null,2));return;
 case 'decision':{const a=visibleApplications().find(a=>a.id===id);download(id+'_Pilot_Karar.json',JSON.stringify({official:false,applicationId:id,title:a.title,decision:a.decision,votes:a.votes},null,2));return;}
 case 'export-decisions':download('Gazi_Pilot_Karar_Arsivi.json',JSON.stringify({official:false,decisions:visibleApplications().filter(a=>a.decision).map(a=>({id:a.id,title:a.title,status:a.status,decision:a.decision,votes:a.votes}))},null,2));return;
 case 'enroll':if(state.enrollments.includes(id))throw Error('Program zaten planınızda.');state.enrollments.push(id);log(state,'Öğrenme planına eklendi',id);if($('#dialog').open)close();toast('Program öğrenme planınıza eklendi.');break;
 case 'unenroll':state.enrollments=state.enrollments.filter(x=>x!==id);log(state,'Öğrenme planından çıkarıldı',id);if($('#dialog').open)close();toast('Öğrenme planı güncellendi.');break;
 case 'read':state.notifications.find(n=>n.id===id).read=true;break;
 case 'read-all':state.notifications.forEach(n=>n.read=true);toast('Bildirimler okundu olarak işaretlendi.');break;
 case 'toggle-task':if(!allowed(state.role,'quality'))throw Error('Kalite veya Koordinatörlük rolünü seçin.');{const q=state.qualityTasks.find(q=>q.id===id);q.status=q.status==='done'?'open':'done';log(state,'Kalite görevi güncellendi',id,q.status);}break;
 case 'new-task':if(!allowed(state.role,'quality'))throw Error('Kalite veya Koordinatörlük rolünü seçin.');modal('İyileştirme görevi',`<form id="task-form"><label class="field">Görev<input name="title" maxlength="140" required></label><label class="field">Sorumlu birim<input name="owner" maxlength="80" value="Kalite Koordinatörlüğü" required></label><label class="field">Hedef tarih<input name="due" type="date" required></label><button class="btn primary">Görevi oluştur</button></form>`);return;
 case 'new-program':if(!allowed(state.role,'program'))throw Error('Eğitici veya Koordinatörlük rolünü seçin.');modal('Yeni program önerisi',`<form id="program-form"><label class="field">Program adı<input name="title" maxlength="120" required></label><label class="field">Öneren birim<input name="unit" maxlength="100" value="GAZİSEM" required></label><label class="field">Toplam iş yükü (saat)<input name="hours" type="number" min="25" max="1800" value="50" required></label><label class="field">Öğrenme çıktıları<textarea name="outcomes" maxlength="2000" required></textarea></label><button class="btn primary">Örnek öneriyi kaydet</button><p>Program önerisi resmî olarak açılmış eğitim anlamına gelmez.</p></form>`);return;
 case 'new-appeal':{if(!allowed(state.role,'appeal'))throw Error('Öğrenen veya Koordinatörlük rolünü seçin.');const aa=visibleApplications().filter(a=>['approved','rejected'].includes(a.status));if(!aa.length)throw Error('İtiraz edilebilecek karara bağlanmış dosya bulunmuyor.');modal('İtiraz kaydı oluştur',`<form id="appeal-form"><label class="field">Karar<select name="applicationId">${aa.map(a=>`<option value="${a.id}">${esc(a.id+' · '+a.title)}</option>`).join('')}</select></label><label class="field">İtiraz gerekçesi<textarea name="reason" minlength="20" maxlength="1800" required></textarea></label><button class="btn primary">İnceleme kaydı aç</button></form>`);return;}
 case 'appeal':{const a=state.appeals.find(a=>a.id===id);modal('Bağımsız itiraz incelemesi',`<p><strong>${esc(a.applicationId)}</strong></p><p>${esc(a.reason)}</p>${a.status==='open'?`<form id="appeal-review-form" data-id="${a.id}"><label class="field">İnceleme sonucu<textarea name="resolution" minlength="20" maxlength="1800" required></textarea></label><button class="btn primary">İncelemeyi kaydet</button></form>${note('appealReview')}`:`<div class="result-box">${esc(a.resolution)}</div>`}`);return;}
 case 'integration':{const s=systems.find(s=>s[0]===id);modal(id+' · Bağlantı hazırlığı',`<p>${s[2]}. Veri sahibi: ${s[1]}.</p><ul class="list"><li>Kurumun veri sözlüğü ve test ortamı sağlanmalı.</li><li>Asgari erişim yetkisi ve kimlik doğrulama tanımlanmalı.</li><li>Tekil işlem anahtarı, hata kuyruğu ve yeniden deneme sınırları belirlenmeli.</li><li>Kayıt, saklama ve geri alma planı doğrulanmalı.</li><li>Kurumsal kullanıcı kabul testi tamamlanmalı.</li></ul>${tag('Canlı bağlantı yok','warn')}<div class="spaced">${btn('Yerel hazırlık kontrolünü kaydet','integration-check',id,'primary')}</div>`);return;}
 case 'integration-check':if(!allowed(state.role,'integration'))throw Error('Bilgi İşlem veya Sistem yöneticisi rolünü seçin.');state.integrationChecks[id]=new Date().toISOString();log(state,'Entegrasyon hazırlığı gözden geçirildi',id,'Canlı bağlantı veya API testi değildir.');close();toast('Hazırlık incelemesi kaydedildi; bağlantı açılmadı.');break;
 case 'reconcile':if(!allowed(state.role,'finance'))throw Error('Mali İşler rolünü seçin.');state.finance.find(f=>f.id===id).state='Mutabık';log(state,'Mali mutabakat provası',id,'Gerçek ödeme veya muhasebe kaydı yok.');toast('Örnek mutabakat tamamlandı.');break;
 case 'backup':download('Gazi_MYYS_Pilot_Yedek.json',JSON.stringify(state,null,2));return;
 case 'reset-confirm':modal('Pilot çalışma alanını sıfırla',`<p>Yalnız bu tarayıcıdaki Gazi örnek kayıtları başlangıç durumuna dönecek. Önce yedek alabilirsiniz.</p><div class="button-row">${btn('Yedeği indir','backup')}${btn('Örnek veriyi sıfırla','reset','','danger')}</div>`);return;
 case 'reset':state=seed();selectedApplication=state.applications[0].id;matchResult=null;close();toast('Gazi pilotu başlangıç örneklerine döndürüldü.');break;
 default:return;
 }save();render();}catch(err){toast(err.message,true);}});
document.addEventListener('submit',e=>{if(!e.target.matches('form'))return;e.preventDefault();const form=e.target,f=new FormData(form);try{switch(form.id){
 case 'application-form':{const a=createApplication(state,{title:f.get('title').trim(),provider:f.get('provider').trim(),hours:Number(f.get('hours')),unit:f.get('unit'),target:f.get('target').trim(),outcomes:f.get('outcomes').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20),evidence:f.has('evidence')});selectedApplication=a.id;matchResult=null;close();save();nav('applications');render();toast('Başvurunuz oluşturuldu: '+a.id);return;}
 case 'match-form':{const a=state.applications.find(a=>a.id===f.get('application'));selectedApplication=a.id;matchResult={...evaluateMatch({hours:Number(f.get('hours')),hoursPerEcts:state.policy.hoursPerEcts,covered:f.getAll('covered').length,total:a.outcomes.length,evidence:f.has('evidence'),issuerChecked:f.has('issuer'),minCoverage:state.policy.minCoverage}),hours:Number(f.get('hours')),evidence:f.has('evidence'),issuerChecked:f.has('issuer')};$('#match-result').innerHTML=renderMatch(matchResult);return;}
 case 'vote-form':recordVote(state,form.dataset.id,{member:f.get('member'),vote:f.get('vote'),reason:f.get('reason').trim(),conflict:f.has('conflict')});close();save();render();application(form.dataset.id);toast('Gerekçeli oy kaydedildi.');return;
 case 'verify-form':{const r=verify(state,f.get('code'));$('#verify-result').innerHTML=`<div class="result-box">${tag(r.label,r.valid?'good':'bad')}${r.credential?`<h3 class="spaced">${esc(r.credential.title)}</h3><p>${r.credential.ects} AKTS · Örnek sicil kaydı</p><small>Resmî belge veya kriptografik doğrulama değildir.</small>`:'<p>Kod bu tarayıcının örnek sicilinde bulunamadı. Kayıt bulunmaması tek başına bir belgenin sahte olduğu anlamına gelmez.</p>'}</div>`;return;}
 case 'revoke-form':{if(!allowed(state.role,'revoke'))throw Error('Öğrenci İşleri rolünü seçin.');const c=state.credentials.find(c=>c.code===form.dataset.id);c.status='revoked';c.revokedReason=f.get('reason').trim();log(state,'Örnek belge iptal edildi',c.code,c.revokedReason);close();toast('İptal durumu sicile işlendi.');break;}
 case 'outcome-form':{const lines=f.get('outcomes').split('\n').map(l=>l.trim()).filter(Boolean);if(!lines.length||lines.length>20)throw Error('1–20 öğrenme çıktısı girin.');const rx=/(analiz eder|değerlendirir|tasarlar|oluşturur|uygular|karşılaştırır|yorumlar|temizler|görselleştirir|hesaplar|çözer|tespit eder|yapılandırır|önerir)/i;$('#outcome-result').innerHTML='<div class="spaced"><h3>Kanıt matrisi</h3>'+lines.map(l=>`<div class="result-box"><strong>${esc(l)}</strong><p>${tag(rx.test(l)?'Gözlenebilir eylem bulundu':'Ölçülebilir eylem ekleyin',rx.test(l)?'good':'warn')}</p><small>Ölçme yöntemi: ${esc(f.get('method'))}</small></div>`).join('')+'</div>';return;}
 case 'task-form':if(!allowed(state.role,'quality'))throw Error('Bu rol görev oluşturamaz.');{const q={id:'Q-'+crypto.randomUUID().slice(0,8),title:f.get('title').trim(),owner:f.get('owner').trim(),due:f.get('due'),status:'open'};state.qualityTasks.push(q);log(state,'Kalite görevi oluşturuldu',q.id,q.title);}close();toast('Görev oluşturuldu.');break;
 case 'program-form':if(!allowed(state.role,'program'))throw Error('Bu rol program öneremez.');{const hours=Number(f.get('hours'));const p={id:'P-'+crypto.randomUUID().slice(0,8),title:f.get('title').trim(),unit:f.get('unit').trim(),hours,ects:Math.round(hours/state.policy.hoursPerEcts*100)/100,category:'Yeni program önerisi',mode:'Planlama aşamasında',outcomes:f.get('outcomes').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,20),icon:'book',color:'blue'};if(!p.title||!p.outcomes.length)throw Error('Program adı ve çıktı girin.');state.programs.unshift(p);log(state,'Program önerisi oluşturuldu',p.id,p.title);}close();toast('Program önerisi kataloğa eklendi.');break;
 case 'appeal-form':if(!allowed(state.role,'appeal'))throw Error('Bu rol itiraz açamaz.');{const a=visibleApplications().find(a=>a.id===f.get('applicationId'));if(!a?.decision)throw Error('Geçerli karar seçin.');if(state.appeals.some(x=>x.applicationId===a.id&&x.status==='open'))throw Error('Bu karar için açık itiraz zaten var.');const x={id:'IT-'+crypto.randomUUID().slice(0,8),applicationId:a.id,owner:a.owner,reason:f.get('reason').trim(),status:'open',at:new Date().toISOString()};state.appeals.push(x);log(state,'İtiraz dosyası açıldı',a.id,x.reason);}close();toast('Bağımsız inceleme kaydı açıldı.');break;
 case 'appeal-review-form':if(!allowed(state.role,'appealReview'))throw Error('Bağımsız inceleme için Kalite Koordinatörlüğü rolünü seçin.');{const a=state.appeals.find(a=>a.id===form.dataset.id);a.resolution=f.get('resolution').trim();a.status='reviewed';log(state,'Bağımsız itiraz incelemesi kaydedildi',a.applicationId,a.resolution);}close();toast('İnceleme kaydedildi; ilk karar korunuyor.');break;
 case 'policy-form':if(!allowed(state.role,'policy'))throw Error('Sistem yöneticisi rolünü seçin.');{const hours=Number(f.get('hours')),coverage=Number(f.get('coverage')),quorum=Number(f.get('quorum')),votes=Number(f.get('votes'));if(hours<25||hours>30||coverage<1||coverage>100||quorum<3||quorum>5||votes<2||votes>quorum||![hours,coverage,quorum,votes].every(Number.isInteger))throw Error('Pilot parametrelerini kontrol edin.');if(state.applications.some(a=>a.status==='commission'&&a.votes.length))throw Error('Oy verilmiş gündem dosyaları varken politika değiştirilemez.');state.policy={hoursPerEcts:hours,minCoverage:coverage,quorum,minVotes:votes,version:'GAZI-PILOT-'+Date.now(),status:'Örnek politika · Kurumsal teyit bekliyor'};state.applications.filter(a=>!['approved','rejected'].includes(a.status)).forEach(a=>{a.match=null;if(a.status==='commission')a.status='review';});matchResult=null;log(state,'Pilot politika sürümlendi',state.policy.version,'Açık eşlemeler yeniden incelemeye alındı.');}toast('Kural sürümü kaydedildi; açık eşlemeler yeniden hesaplanmalı.');break;
 default:return;
 }save();render();}catch(err){toast(err.message,true);}});
$('#role').addEventListener('change',e=>{state.role=e.target.value;matchResult=null;query='';filter='all';save();render();});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}if(e.target.id==='match-app'){selectedApplication=e.target.value;matchResult=null;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const p=e.target.selectionStart;render();const input=$('#search');input.focus();input.setSelectionRange(p,p);}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#veil').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));});$('#veil').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#veil').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#veil').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{query='';filter='all';if($('#dialog').open)close();render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);});
render();
